    if(shared){map='<div class="lx-breadcrumb">'+esc(d.destination.name)+'</div><section class="lx-world ftc-ai-map" data-ftc-ai-map aria-label="Gemeinsame Places-Karte des Reiseentwurfs"></section>';body=body.replace(/<section class="ftc-ai-map"[^>]*><\/section>/,'');}
    const nextLabel=step==='welcome'?(level===0?(CONTINENT_LABELS[state.worldView?.continent||'Europe']||'Europa')+' entdecken':level===1?'Land entdecken':level===2?'Dieses Land als Ziel wählen':'Diese Region als Ziel wählen'):step==='destination'?'Reisezeit entdecken':step==='dates'?(hasSuggestions(state)?'Reisegefühl gestalten':'Reise gestalten'):step==='brief'?(d.entryMode==='ai'?'Reiseideen entwickeln':'Vorschläge entdecken'):step==='preview'?'Auswahl mitnehmen':'Reise ansehen';
    const dream=dreaming(state),collapsed=state.sheetCollapsed===true,title=dream?'Eure Reise beginnt mit einem Wunsch.':titles[step],modeNav=!dream&&step==='welcome'?'<nav class="lx-modes" aria-label="Art der Reiseerstellung">'+['quick','guided','ai'].map(id=>'<button type="button" data-ftc-entry-mode="'+id+'" aria-pressed="'+(d.entryMode===id)+'">'+ENTRY_LABELS[id]+'</button>').join('')+'</nav>':'';
