  function toast(state,title,message){clearTimeout(state.toastTimer);const node=state.root.querySelector('[data-ftc-toast]');if(!node)return;node.querySelector('strong').textContent=title;node.querySelector('small').textContent=message;node.hidden=false;state.toastTimer=setTimeout(()=>{if(node.isConnected)node.hidden=true},3400);}
  function validate(state,index=state.index){
    const step=currentFlow(state)[index],d=state.data;
    if(step==='identity'&&!d.title.trim())return ['Ein Name fehlt','Gebt eurer Reise einen Namen.'];
    if(step==='feeling'&&!d.feelings.length)return ['Ein Gefühl fehlt','Wählt mindestens ein Reisegefühl.'];
    if(step==='destination'&&!d.destination?.placeId)return ['Der Ort ist noch nicht bestätigt','Wählt bitte einen Vorschlag aus der Suche.'];
    if(step==='dates'&&d.scheduleMode==='fixed'&&(!validDate(d.startDate)||!validDate(d.endDate)||d.endDate<d.startDate))return ['Der Zeitraum passt noch nicht','Bitte gültige Anreise und Rückreise eintragen. Die Rückreise darf nicht vor der Anreise liegen.'];
    if(step==='preview'&&state.aiDraft?.status!=='ready')return ['Entwurf noch nicht bereit','Bitte wartet auf die Vorschläge oder versucht es erneut.'];
    if(step==='dates'&&d.entryMode!=='quick'&&d.scheduleMode==='fixed'&&!validZone(tripZone(state)))return ['Ortszeit noch nicht bestätigt','Die Quelle hat noch keine eindeutige Ortszeit geliefert. Bitte wählt euer Ziel erneut oder einen konkreteren Ort.'];
    if(step==='modules'&&!d.modules.length)return ['Kein Reisebaustein aktiv','Wählt mindestens einen Bereich.'];
    return null;
  }
  function projectStep(state,replace=false){const nav=window.LuviaNavigationContractV1,history=window.LuviaNavigationHistoryV1;if(!nav?.createIntent||!history?.project)return;history.project(nav.createIntent(ROUTE,{source:'first-trip-composer',replace,params:{tripStep:currentStep(state),tripMode:state.mode,tripEntry:state.data.entryMode,returnTo:state.options.returnTo||'today'}}),{replace,source:'first-trip-composer'});}
  function go(state,index,{skipValidation=false}={}){const flow=currentFlow(state);if(state.saving||state.confirmation||index<0||index>=flow.length)return;if(currentStep(state)==='welcome'&&!state.openingComplete&&index>0){state.openingComplete=true;render(state,{focus:true});return;}if(index>state.index&&!skipValidation){const problem=validate(state);if(problem)return toast(state,...problem);}state.sheetCollapsed=false;state.index=index;state.highest=Math.max(state.highest,index);projectStep(state);render(state,{focus:true});}
  async function places(){const api=window.LuviaPlacesContractV1;if(!api?.reads?.suggestDestinations||!api?.reads?.getDestination)throw new Error('Der öffentliche Places-Contract ist noch nicht verfügbar.');return api;}
  function within(promise,timeoutMs=8500,message='Die Zielsuche hat zu lange gedauert.',code='PLACES_DESTINATION_TIMEOUT'){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{const error=new Error(message);error.code=code;reject(error)},timeoutMs);Promise.resolve(promise).then(value=>{clearTimeout(timer);resolve(value)},error=>{clearTimeout(timer);reject(error)})})}
  async function details(placeId){const api=await places();const destination=await api.reads.getDestination(placeId,{languageCode:'de',regionCode:'DE',sessionToken:placesSessionToken});if(destination?.owner!=='places'||destination?.contractId!=='places.v1'||!destination?.placeId)throw new Error('Places hat das Reiseziel nicht kanonisch bestätigt.');return {name:destination.name,formattedAddress:destination.formattedAddress,country:destination.country,countryCode:destination.countryCode,placeId:destination.placeId,latitude:destination.latitude??null,longitude:destination.longitude??null,timezone:destination.timezone||''};}
  const providerId=place=>String(place?.providerPlaceId||place?.provider_place_id||place?.id||'').replace(/^places\//,'').trim();
  const placeCoordinates=place=>{const source=place?.coordinates||place?.location||{},lat=source.latitude??source.lat,lng=source.longitude??source.lng,latitude=Number(lat),longitude=Number(lng);return lat!=null&&lng!=null&&lat!==''&&lng!==''&&Number.isFinite(latitude)&&Number.isFinite(longitude)&&Math.abs(latitude)<=90&&Math.abs(longitude)<=180?{latitude,longitude}:null};
  const validDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')&&!Number.isNaN(Date.parse(value+'T12:00:00Z'))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
  const placeLabel=place=>({restaurant:'Restaurant',cafe:'Café',museum:'Museum',art_gallery:'Galerie',park:'Park',bar:'Bar',night_club:'Club',tourist_attraction:'Sehenswürdigkeit',sports_activity_location:'Aktivität',spa:'Wellness'}[place.primaryType]||'Ort zum Entdecken');
  const dateLabel=value=>validDate(value)?new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):'Termin offen';
  const tripZone=state=>state.data.destination?.timezone||'';
